def test_validate_schema_missing_fields(prover):
    """Ensure missing required fields raise ValueError."""
    with pytest.raises(ValueError, match="SYNTAX_ERR: Missing required field 'formula'"):
        prover._validate_schema({"logic_type": LogicType.SMT})
    
    with pytest.raises(ValueError, match="SYNTAX_ERR: Missing required field 'logic_type'"):
        prover._validate_schema({"formula": "(assert true)"})

def test_parse_s_expression_simple(prover):
    """Test parsing of basic atoms and simple lists."""
    assert prover._parse_s_expression("atom") == "atom"
    assert prover._parse_s_expression("(a b c)") == ["a", "b", "c"]

def test_parse_s_expression_nested(prover):
    """Test complex nested S-expressions."""
    expr = "(forall (x Int) (=> (> x 0) (> (+ x 1) 1)))"
    expected = ['forall', ['x', 'Int'], ['=>', ['>', 'x', '0'], ['>', ['+', 'x', '1'], '1']]]
    # Note: The parser treats numbers as strings unless cast, which matches the provided implementation
    result = prover._parse_s_expression(expr)
    assert result[0] == 'forall'
    assert isinstance(result[2], list)
    assert result[2][0] == '=>'

def test_simplify_to_nnf_double_negation(prover):
    """Test that (not (not P)) simplifies to P."""
    formula = ['not', ['not', 'P']]
    assert prover._simplify_to_nnf(formula) == 'P'

def test_simplify_to_nnf_single_negation(prover):
    """Test that single negation is preserved."""
    formula = ['not', 'P']
    assert prover._simplify_to_nnf(formula) == ['not', 'P']

def test_simplify_to_nnf_recursive(prover):
    """Test simplification within nested structures."""
    formula = ['and', ['not', ['not', 'P']], 'Q']
    assert prover._simplify_to_nnf(formula) == ['and', 'P', 'Q']

