def test_prove_orchestration_flow(prover, valid_payload):
    """Test the full prove() pipeline using mocks to isolate Z3."""
    with patch.object(LogicProver, '_execute_z3_solver') as mock_z3:
        mock_z3.return_value = VerificationResult(Verdict.VALID, proof_trace=["Mocked Proof"])
        
        # Force Z3_AVAILABLE to True for this test to bypass simulation
        with patch('logic_prover.Z3_AVAILABLE', True):
            result = prover.prove(valid_payload)
            
            assert result.verdict == Verdict.VALID
            assert result.proof_trace == ["Mocked Proof"]
            mock_z3.assert_called_once()

def test_prove_exception_handling(prover, valid_payload):
    """Test that unexpected exceptions in the pipeline return Verdict.UNKNOWN."""
    with patch.object(LogicProver, '_parse_s_expression', side_effect=RuntimeError("Crash")):
        result = prover.prove(valid_payload)
        assert result.verdict == Verdict.UNKNOWN
        assert "Error: Crash" in result.proof_trace[0]

